// Writes the theme CSS for each app from tokens.json. Run with `npm run tokens` after editing it.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const HEADER = `/*
 * Generated from tokens.json by generate.mjs. Do not edit this file.
 *
 * Values come from the Figma file "WPI Day 1.5 (P&A and P&E)", by way of the Alfred mock UI.
 * Light only: the design has no dark palette yet.
 */
`;

const vars = (entries, indent) => entries.map(([name, value]) => `${indent}--${name}: ${value};`).join("\n");
const prefixed = (prefix, group) => Object.entries(group).map(([key, value]) => [`${prefix}-${key}`, value]);

/** Website: a Tailwind v4 theme. Tailwind's default colors are removed, so only Figma colors exist. */
export function renderWeb(tokens) {
  const theme = [
    ["color-*", "initial"],
    ...prefixed("font", tokens.font),
    ...prefixed("color", tokens.color),
    ...Object.entries(tokens.text).flatMap(([key, { size, lineHeight }]) => [
      [`text-${key}`, size],
      [`text-${key}--line-height`, lineHeight],
    ]),
    ...prefixed("radius", tokens.radius),
    ...prefixed("shadow", tokens.shadow),
    ...prefixed("container", tokens.container),
  ];
  const gradients = Object.entries(tokens.gradient)
    .map(([key, value]) => `@utility bg-${key} {\n  background-image: ${value};\n}`)
    .join("\n");
  return `${HEADER}@theme {
${vars(theme, "  ")}
}

/* Named Figma gradients */
${gradients}
/* 1px gradient border (Figma "Field" stroke): white fill with the AI gradient as the border. */
@utility border-ai {
  border: 1px solid transparent;
  background:
    linear-gradient(${tokens.color.white}, ${tokens.color.white}) padding-box,
    ${tokens.gradient.ai} border-box;
}
`;
}

/**
 * Mobile app: Uniwind theme variables. React Native has no CSS gradients or shadows like these, so only
 * colors and radii are written. Dark mode uses the light values until the design has a dark palette.
 */
export function renderNative(tokens) {
  const colors = vars(prefixed("color", tokens.color), "      ");
  return `${HEADER}@layer theme {
  :root {
    @variant light {
${colors}
    }
    @variant dark {
${colors}
    }
  }
}

@theme {
${vars(prefixed("radius", tokens.radius), "  ")}
}
`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const tokens = JSON.parse(readFileSync(new URL("./tokens.json", import.meta.url), "utf8"));
  mkdirSync(new URL("./generated/", import.meta.url), { recursive: true });
  writeFileSync(new URL("./generated/principal.css", import.meta.url), renderWeb(tokens));
  writeFileSync(new URL("./generated/uniwind.css", import.meta.url), renderNative(tokens));
}
